/** The template of a document, or undefined where it has none (its download is the generic one). */
export function originalFileOf(documentId: string): OriginalFile | undefined {
  return Object.prototype.hasOwnProperty.call(ORIGINAL_FILES, documentId) ? ORIGINAL_FILES[documentId] : undefined;
}
